package org.lucasmendss;

import java.awt.*;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;

public class SearchEmployeeWindow extends Frame {

    private TextField nomeABuscar = new TextField("", 30);
    private TextField nome = new TextField("", 30);
    private TextField salario = new TextField("", 30);
    private TextField cargo = new TextField("", 30);
    private Button pesquisar = new Button("Pesquisar");
    private Button anterior = new Button("Anterior");
    private Button proximo = new Button("Próximo");
    private boolean primeiraBuscaFeita = false;
    private List<String[]> funcionarios = new ArrayList<>();
    private int indiceAtual = -1;
    private PreparedStatement stmt;
    private Connection conn;

    public SearchEmployeeWindow() {
        super("TRABALHO PRATICO 04");

        setLayout(new BorderLayout(10, 10));
        setSize(400, 275);
        setLocationRelativeTo(null);
        setResizable(false);
        setBackground(Color.GRAY);

        addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosing(WindowEvent e) {
                try {
                    if (stmt != null) {
                        stmt.close();
                    }
                    if (conn != null) {
                        conn.close();
                    }
                } catch (SQLException ex) {
                    System.out.println("Erro ao fechar conexão: " + ex.getMessage());
                }
                dispose();
            }
        });

        nome.setEditable(false);
        salario.setEditable(false);
        cargo.setEditable(false);

        pesquisar.addActionListener(e -> pesquisarFuncionario());
        anterior.addActionListener(e -> anterior());
        proximo.addActionListener(e -> proximo());

        Panel topo = new Panel(new FlowLayout(FlowLayout.LEFT, 10, 10));
        Label lblNome = new Label("Nome:");

        topo.add(lblNome);
        topo.add(nomeABuscar);
        add(topo, BorderLayout.NORTH);

        Panel linhaBusca = new Panel(new FlowLayout(FlowLayout.CENTER, 0, 0));
        linhaBusca.add(pesquisar);
        add(linhaBusca, BorderLayout.CENTER);

        Panel dados = new Panel(new GridLayout(4, 2, 10, 10));
        dados.setBackground(Color.LIGHT_GRAY);

        Label nomeLabel = new Label("Nome:");
        Label salarioLabel = new Label("Salário:");
        Label cargoLabel = new Label("Cargo:");

        dados.add(nomeLabel);
        dados.add(nome);
        dados.add(salarioLabel);
        dados.add(salario);
        dados.add(cargoLabel);
        dados.add(cargo);
        dados.add(anterior);
        dados.add(proximo);

        add(dados, BorderLayout.SOUTH);
        setVisible(true);
    }

    private void mostrarFuncionarioAtual() {
        if (funcionarios.isEmpty() || indiceAtual < 0 || indiceAtual >= funcionarios.size()) {
            limparCampos();
            return;
        }

        String[] funcionario = funcionarios.get(indiceAtual);
        nome.setText(funcionario[0]);
        salario.setText(funcionario[1]);
        cargo.setText(funcionario[2]);

        nome.repaint();
        salario.repaint();
        cargo.repaint();
        validate();
        repaint();
    }

    private void limparCampos() {
        nome.setText("");
        salario.setText("");
        cargo.setText("");

        nome.repaint();
        salario.repaint();
        cargo.repaint();
    }

    private void pesquisarFuncionario(){
        try {
            if (conn == null || conn.isClosed()) {
                conn = ConnectionFactory.getConnection();
            }

            String termoBusca = nomeABuscar.getText().trim();
            String sql = "SELECT f.nome_func, f.sal_func, c.ds_cargo " +
                    "FROM tbfuncs f INNER JOIN tbcargos c ON c.cd_cargo = f.cod_cargo ";

            if (!termoBusca.isEmpty()) {
                sql += "WHERE UPPER(f.nome_func) LIKE ? ORDER BY f.nome_func";
            } else {
                sql += "ORDER BY f.nome_func";
            }

            if (stmt != null) {
                stmt.close();
            }

            stmt = conn.prepareStatement(sql);

            if (!termoBusca.isEmpty()) {
                stmt.setString(1, "%" + termoBusca.toUpperCase() + "%");
            }

            ResultSet rs = stmt.executeQuery();
            funcionarios.clear();

            while (rs.next()) {
                funcionarios.add(new String[]{
                        rs.getString("nome_func"),
                        String.valueOf(rs.getDouble("sal_func")),
                        rs.getString("ds_cargo")
                });
            }

            rs.close();
            primeiraBuscaFeita = true;

            if (!funcionarios.isEmpty()) {
                indiceAtual = 0;
                EventQueue.invokeLater(this::mostrarFuncionarioAtual);
            } else {
                indiceAtual = -1;
                limparCampos();
            }
        } catch (Exception e) {
            System.out.println("Erro: " + e.getMessage());
        }
    }

    private void anterior(){
        if (!primeiraBuscaFeita || funcionarios.isEmpty()) {
            pesquisarFuncionario();
            return;
        }

        if (indiceAtual > 0) {
            indiceAtual--;
        } else {
            indiceAtual = funcionarios.size() - 1;
        }

        EventQueue.invokeLater(this::mostrarFuncionarioAtual);
    }

    private void proximo(){
        if (!primeiraBuscaFeita || funcionarios.isEmpty()) {
            pesquisarFuncionario();
            return;
        }

        if (indiceAtual < funcionarios.size() - 1) {
            indiceAtual++;
        } else {
            indiceAtual = 0;
        }

        EventQueue.invokeLater(this::mostrarFuncionarioAtual);
    }
}

package org.lucasmendss;

import java.awt.*;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;

public class SearchEmployeeWindow extends Frame {

    private static class Funcionario {
        private final String nome;
        private final String salario;
        private final String cargo;

        public Funcionario(String nome, String salario, String cargo) {
            this.nome = nome;
            this.salario = salario;
            this.cargo = cargo;
        }
    }

    private TextField nomeABuscar = new TextField("", 30);
    private TextField nome = new TextField("", 30);
    private TextField salario = new TextField("", 30);
    private TextField cargo = new TextField("", 30);
    private Button pesquisar = new Button("Pesquisar");
    private Button anterior = new Button("Anterior");
    private Button proximo = new Button("Próximo");
    private boolean primeiraBuscaFeita = false;
    private List<Funcionario> funcionarios = new ArrayList<>();
    private int indiceAtual = -1;
    private PreparedStatement stmt;
    private Connection conn;

    public SearchEmployeeWindow() {
        super("TRABALHO PRATICO 04");

        setLayout(new BorderLayout(10, 10));
        setSize(400, 275);
        setLocationRelativeTo(null);
        setResizable(false);
        setBackground(Color.GRAY);

        addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosing(WindowEvent e) {
                try {
                    if (stmt != null) {
                        stmt.close();
                    }
                    if (conn != null) {
                        conn.close();
                    }
                } catch (SQLException ex) {
                    System.out.println("Erro ao fechar conexão: " + ex.getMessage());
                }
                dispose();
            }
        });

        nome.setEditable(false);
        salario.setEditable(false);
        cargo.setEditable(false);

        pesquisar.addActionListener(e -> pesquisarFuncionario());
        anterior.addActionListener(e -> anterior());
        proximo.addActionListener(e -> proximo());

        Panel topo = new Panel(new FlowLayout(FlowLayout.LEFT, 10, 10));
        Label lblNome = new Label("Nome:");

        topo.add(lblNome);
        topo.add(nomeABuscar);
        add(topo, BorderLayout.NORTH);

        Panel linhaBusca = new Panel(new FlowLayout(FlowLayout.CENTER, 0, 0));
        linhaBusca.add(pesquisar);
        add(linhaBusca, BorderLayout.CENTER);

        Panel dados = new Panel(new GridLayout(4, 2, 10, 10));
        dados.setBackground(Color.LIGHT_GRAY);

        Label nomeLabel = new Label("Nome:");
        Label salarioLabel = new Label("Salário:");
        Label cargoLabel = new Label("Cargo:");

        dados.add(nomeLabel);
        dados.add(nome);
        dados.add(salarioLabel);
        dados.add(salario);
        dados.add(cargoLabel);
        dados.add(cargo);
        dados.add(anterior);
        dados.add(proximo);

        add(dados, BorderLayout.SOUTH);
        setVisible(true);
    }

    private void mostrarFuncionarioAtual() {
        if (funcionarios.isEmpty() || indiceAtual < 0 || indiceAtual >= funcionarios.size()) {
            limparCampos();
            return;
        }

        Funcionario funcionario = funcionarios.get(indiceAtual);
        nome.setText(funcionario.nome);
        salario.setText(funcionario.salario);
        cargo.setText(funcionario.cargo);

        System.out.println("Exibindo funcionário: " + funcionario.nome);
        nome.repaint();
        salario.repaint();
        cargo.repaint();
        validate();
        repaint();
    }

    private void limparCampos() {
        nome.setText("");
        salario.setText("");
        cargo.setText("");
        repaint();
    }

    private void pesquisarFuncionario(){
        try {
            if (conn == null || conn.isClosed()) {
                conn = ConnectionFactory.getConnection();
            }

            String termoBusca = nomeABuscar.getText().trim();
            String sql = "SELECT f.nome_func, f.sal_func, c.ds_cargo " +
                    "FROM tbfuncs f INNER JOIN tbcargos c ON c.cd_cargo = f.cod_cargo ";

            if (!termoBusca.isEmpty()) {
                sql += "WHERE UPPER(f.nome_func) LIKE ? ORDER BY f.nome_func";
            } else {
                sql += "ORDER BY f.nome_func";
            }

            if (stmt != null) {
                stmt.close();
            }

            stmt = conn.prepareStatement(sql);

            if (!termoBusca.isEmpty()) {
                stmt.setString(1, "%" + termoBusca.toUpperCase() + "%");
            }

            ResultSet rs = stmt.executeQuery();
            funcionarios.clear();

            while (rs.next()) {
                funcionarios.add(new Funcionario(
                        rs.getString("nome_func"),
                        String.valueOf(rs.getDouble("sal_func")),
                        rs.getString("ds_cargo")
                ));
            }

            rs.close();
            primeiraBuscaFeita = true;

            if (!funcionarios.isEmpty()) {
                indiceAtual = 0;
                mostrarFuncionarioAtual();
            } else {
                indiceAtual = -1;
                limparCampos();
            }
        } catch (Exception e) {
            System.out.println("Erro: " + e.getMessage());
        }
    }

    private void anterior(){
        if (!primeiraBuscaFeita || funcionarios.isEmpty()) {
            pesquisarFuncionario();
            return;
        }

        if (indiceAtual > 0) {
            indiceAtual--;
        } else {
            indiceAtual = funcionarios.size() - 1;
        }

        System.out.println("Anterior -> indice: " + indiceAtual);
        mostrarFuncionarioAtual();
    }

    private void proximo(){
        if (!primeiraBuscaFeita || funcionarios.isEmpty()) {
            pesquisarFuncionario();
            return;
        }

        if (indiceAtual < funcionarios.size() - 1) {
            indiceAtual++;
        } else {
            indiceAtual = 0;
        }

        System.out.println("Próximo -> indice: " + indiceAtual);
        mostrarFuncionarioAtual();
    }
}
